import {activities,sources} from './data/activities.js';
import {casesEn} from './data/cases-en.js';
import {extraCases} from './data/cases-extra.js';
import {learningMap} from './data/learning-map-data.js';

export function getCases(lang='en'){
 const en=lang==='en',index=en?0:1;
 const existing=activities.map(a=>{const text=en?casesEn[a.id]:a,s=sources[a.source];return {...a,...text,skillId:s.id,skillName:en?s.name:s.zh,skillAge:s.age,ltl:learningMap.topics.some(n=>n.id===s.id),sourceLine:s.line};});
 const extra=extraCases.map(row=>{const [skillId,title,materials,steps,observations,question]=row,n=learningMap.topics.find(t=>t.id===skillId);return{id:'case-'+skillId,skillId,skillName:en?n.name:n.zh,skillAge:[n.ageRangeStart,n.ageRangeEnd],ltl:true,sourceLine:n.sourceLine,title:title[index],summary:en?n.descriptionEn:n.description,materials:materials[index],steps:steps.map((s,i)=>[(en?['Set up · 4 min','Try together · 11 min','Reflect · 5 min']:['准备 · 4分钟','一起尝试 · 11分钟','回顾 · 5分钟'])[i],s[index]]),question:question[index],observations:observations.map(o=>o[index]),prep:en?'Choose a manageable version together. Pause or offer help when needed; reference ages are not deadlines.':'一起选择难度合适的版本，需要时暂停或提供帮助；参考年龄不是达标期限。'};});
 const all=[...existing,...extra];
 return [...learningMap.topics.map(n=>all.find(a=>a.skillId===n.id)),...all.filter(a=>!a.ltl)];
}

export function getFreeCase(lang='en'){
 const en=lang==='en';
 return {id:'open-exploration',custom:true,skillId:'self-directed-exploration',skillName:en?'Child-led exploration':'孩子自主探索',title:en?'Make something of your own':'玩一个自己想出来的点子',observations:en?['Expressed an idea or a question to explore','Tried something and changed the approach when needed','Described what happened or what to try next']:['说出一个想尝试的点子或问题','动手尝试，并在需要时调整做法','说出发现了什么，或下一次想试什么']};
}

